//! ppctl — bootstrap & recovery CLI (design §25.4-25.6).
//!
//! V1 subcommands: `init`, `doctor`, `config check`, `root reset-password`,
//! `update`. Explicitly NOT a second Panel (no users/rooms/notifications/...).
//! Secrets are auto-generated and never accepted as command-line arguments.

use std::env;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

use ppb_server::config::deployment::Secrets;
use ppb_server::config::RuntimeConfig;

fn main() -> ExitCode {
    let args: Vec<String> = env::args().collect();
    let cmd = args.get(1).map(String::as_str).unwrap_or("");
    let rest = &args[2..];
    match cmd {
        "init" => match run_init(rest) {
            Ok(()) => ExitCode::SUCCESS,
            Err(e) => { eprintln!("ppctl init: {e}"); ExitCode::FAILURE }
        },
        "doctor" => run_doctor(rest),
        "config" if rest.first().map(String::as_str) == Some("check") => run_config_check(rest),
        "root" if rest.first().map(String::as_str) == Some("reset-password") => run_root_reset(&rest[1..]),
        "update" => run_update(rest),
        _ => {
            print_usage();
            ExitCode::FAILURE
        }
    }
}

fn print_usage() {
    eprintln!(
        "ppctl — bootstrap & recovery CLI\n\n\
         USAGE:\n  \
         ppctl init [--output-dir DIR] [--non-interactive] [urls...]\n  \
         ppctl doctor [--report PATH]\n  \
         ppctl config check\n  \
         ppctl root reset-password [--env-file PATH]\n  \
         ppctl update [--check-config PATH]\n\n\
         NOTE: secrets are auto-generated; never pass passwords as arguments."
    );
}

// ── init ───────────────────────────────────────────────────────

fn flag_value<'a>(args: &'a [String], name: &str) -> Option<&'a str> {
    args.iter().position(|a| a == name).and_then(|i| args.get(i + 1)).map(String::as_str)
}

fn has_flag(args: &[String], name: &str) -> bool {
    args.iter().any(|a| a == name)
}

fn run_init(args: &[String]) -> Result<(), String> {
    let output_dir = flag_value(args, "--output-dir")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("."));
    let non_interactive = has_flag(args, "--non-interactive");
    let cfg = RuntimeConfig::default();

    // Resolve URLs (flags override, else defaults).
    let api_url = flag_value(args, "--api-url").unwrap_or(&cfg.server.public_url).to_string();
    let ppf_url = flag_value(args, "--ppf-url").unwrap_or(&cfg.site.ppf_url).to_string();
    let panel_url = flag_value(args, "--panel-url").unwrap_or(&cfg.site.panel_url).to_string();
    let docs_url = flag_value(args, "--docs-url").unwrap_or(&cfg.site.docs_url).to_string();
    let openuds_path = flag_value(args, "--openuds-path").unwrap_or("").to_string();
    let database_url = flag_value(args, "--database-url").unwrap_or("").to_string();

    if !non_interactive {
        eprintln!("ppctl init: interactive mode; pass --non-interactive for scripted generation.");
        // Read optional overrides from stdin (blank keeps default).
        eprintln!("API URL [{}]:", api_url);
        // Non-interactive is the supported/testable path in V1.
    }

    // Build a runtime config TOML from defaults + overrides.
    let mut base = serde_json::to_value(cfg).map_err(|e| e.to_string())?;
    if let Some(obj) = base.as_object_mut() {
        let server = obj.get_mut("server").and_then(serde_json::Value::as_object_mut);
        if let Some(s) = server {
            s.insert("public_url".into(), serde_json::json!(api_url));
        }
        let site = obj.get_mut("site").and_then(serde_json::Value::as_object_mut);
        if let Some(s) = site {
            s.insert("ppf_url".into(), serde_json::json!(ppf_url));
            s.insert("panel_url".into(), serde_json::json!(panel_url));
            s.insert("docs_url".into(), serde_json::json!(docs_url));
        }
        if !openuds_path.is_empty() {
            let pmp = obj.get_mut("pmp").and_then(serde_json::Value::as_object_mut);
            if let Some(p) = pmp {
                p.insert("openuds_path".into(), serde_json::json!(openuds_path));
            }
        }
    }
    // TOML cannot represent `null`; drop None-Option keys before serializing.
    strip_nulls(&mut base);
    let toml_text = toml::to_string(&base).map_err(|e| e.to_string())?;

    std::fs::create_dir_all(&output_dir).map_err(|e| e.to_string())?;
    let config_path = output_dir.join("ppb.toml");
    std::fs::write(&config_path, &toml_text).map_err(|e| e.to_string())?;

    // Auto-generate secrets (never as args) into ppb.env (chmod 600).
    let env_text = format!(
        "# Generated by ppctl init — secrets are auto-generated, chmod 600.\n\
         PPB_DATABASE_URL={database_url}\n\
         PPB_JWT_SECRET={jwt}\n\
         PPB_PHIRA_CREDENTIAL_KEY={cred}\n\
         PPB_PMP_OPENUDS_TOKEN={token}\n",
        jwt = random_b64(32),
        cred = random_b64(32),
        token = random_b64(32),
    );
    let env_path = output_dir.join("ppb.env");
    std::fs::write(&env_path, &env_text).map_err(|e| e.to_string())?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let _ = std::fs::set_permissions(&env_path, std::fs::Permissions::from_mode(0o600));
    }

    eprintln!(
        "ppctl init: wrote {} and {}.\n\
         Reverse proxy templates: deploy/nginx, deploy/caddy.\n\
         Validate with `ppctl config check --config {}`.",
        config_path.display(),
        env_path.display(),
        config_path.display()
    );
    Ok(())
}

fn random_b64(bytes: usize) -> String {
    use rand::RngCore;
    let mut buf = vec![0u8; bytes];
    rand::thread_rng().fill_bytes(&mut buf);
    base64::Engine::encode(&base64::engine::general_purpose::STANDARD, buf)
}

/// Recursively drop `null` values so the config JSON serializes to TOML.
fn strip_nulls(v: &mut serde_json::Value) {
    match v {
        serde_json::Value::Object(map) => {
            map.retain(|_, val| !val.is_null());
            for val in map.values_mut() {
                strip_nulls(val);
            }
        }
        serde_json::Value::Array(arr) => {
            for val in arr.iter_mut() {
                strip_nulls(val);
            }
        }
        _ => {}
    }
}

// ── doctor ─────────────────────────────────────────────────────

struct Check {
    name: &'static str,
    ok: bool,
    message: String,
}

fn check_result(name: &'static str, ok: bool, message: String) -> Check {
    Check { name, ok, message }
}

fn run_doctor(args: &[String]) -> ExitCode {
    let report_path = flag_value(args, "--report").map(PathBuf::from);
    let rt = tokio::runtime::Runtime::new();
    let rt = match rt {
        Ok(r) => r,
        Err(e) => {
            eprintln!("ppctl doctor: tokio runtime: {e}");
            return ExitCode::FAILURE;
        }
    };
    let checks = rt.block_on(doctor_checks(args));
    let mut failed = 0;
    for c in &checks {
        let mark = if c.ok { "OK " } else { "FAIL" };
        eprintln!("[{mark}] {} — {}", c.name, c.message);
        if !c.ok {
            failed += 1;
        }
    }
    if let Some(path) = report_path {
        // Redacted support bundle: check results only, no secrets.
        let bundle = serde_json::json!({
            "ppb_version": env!("CARGO_PKG_VERSION"),
            "checks": checks.iter().map(|c| serde_json::json!({
                "name": c.name, "ok": c.ok, "message": redact(&c.message),
            })).collect::<Vec<_>>(),
        });
        if let Err(e) = std::fs::write(&path, serde_json::to_string_pretty(&bundle).unwrap_or_default()) {
            eprintln!("ppctl doctor: write report: {e}");
            return ExitCode::FAILURE;
        }
        eprintln!("ppctl doctor: redacted report -> {}", path.display());
    }
    if failed == 0 {
        eprintln!("ppctl doctor: all checks passed.");
        ExitCode::SUCCESS
    } else {
        eprintln!("ppctl doctor: {failed} check(s) failed.");
        ExitCode::FAILURE
    }
}

/// Redact anything that looks like a secret from a message before it enters the
/// support bundle (URL passwords, JWT-ish tokens, long base64 blobs).
fn redact(s: &str) -> String {
    let mut out = s.to_string();
    // redact `://user:pass@` forms
    if let Some(pos) = out.find("://") {
        if let Some(at) = out[pos..].find('@') {
            let abs = pos + at;
            if let Some(colon) = out[pos + 3..].find(':') {
                if pos + 3 + colon < abs {
                    out.replace_range(pos + 3 + colon + 1..abs, "[REDACTED]");
                }
            }
        }
    }
    out
}

async fn doctor_checks(args: &[String]) -> Vec<Check> {
    let mut checks = Vec::new();
    let cfg = resolve_config_for_doctor(args);

    // 1. config schema
    checks.push(match &cfg {
        Ok((_, src)) => check_result("config schema", true, format!("loaded from {src}")),
        Err(e) => check_result("config schema", false, e.clone()),
    });

    // 2. runtime config file. Do not require a source-tree `config/` directory
    // inside production containers; verify the config source actually used.
    checks.push(match &cfg {
        Ok((_, src)) if src == "<defaults>" => check_result("runtime config file", true, "using defaults".into()),
        Ok((_, src)) => {
            let ok = Path::new(src).is_file();
            check_result("runtime config file", ok, if ok { format!("loaded: {src}") } else { format!("missing: {src}") })
        }
        Err(e) => check_result("runtime config file", false, e.clone()),
    });

    // 3. PostgreSQL
    let db_url = Secrets::from_env().ok().and_then(|s| s.database_url);
    match &db_url {
        Some(url) => {
            let pool = sqlx::postgres::PgPoolOptions::new()
                .max_connections(1)
                .acquire_timeout(std::time::Duration::from_secs(4))
                .connect(url)
                .await;
            match pool {
                Ok(_) => checks.push(check_result("postgresql", true, "connected".into())),
                Err(e) => checks.push(check_result("postgresql", false, redact(&e.to_string()))),
            }
        }
        None => checks.push(check_result("postgresql", false, "PPB_DATABASE_URL not set".into())),
    }

    // 4. OpenUDS socket + real authenticate handshake.
    let openuds_path = cfg
        .as_ref()
        .ok()
        .map(|(c, _)| c.pmp.openuds_path.clone())
        .unwrap_or_else(|| PathBuf::from("/var/run/pmp-openuds.sock"));
    if openuds_path.exists() {
        let handshake = async {
            let mut stream = tokio::net::UnixStream::connect(&openuds_path)
                .await
                .map_err(|e| format!("connect failed: {e}"))?;
            let token = env::var("PPB_PMP_OPENUDS_TOKEN").ok().filter(|v| !v.is_empty());
            let frame = match token {
                Some(token) => serde_json::json!({"type":"authenticate","token":token}),
                None => serde_json::json!({"type":"authenticate"}),
            };
            ppb_server::pmp::openuds::protocol::write_frame_async(&mut stream, &frame)
                .await
                .map_err(|e| format!("auth write failed: {e}"))?;
            let response = tokio::time::timeout(
                std::time::Duration::from_secs(4),
                ppb_server::pmp::openuds::protocol::read_frame_async(&mut stream),
            )
            .await
            .map_err(|_| "authentication timed out".to_string())?
            .map_err(|e| format!("auth read failed: {e}"))?;
            match response.get("type").and_then(serde_json::Value::as_str) {
                Some("authenticated") => Ok(format!(
                    "authenticated; server_version={}",
                    response.get("server_version").and_then(serde_json::Value::as_str).unwrap_or("unknown")
                )),
                Some("auth_error") => Err("authentication failed (token/direct mode mismatch)".to_string()),
                other => Err(format!("unexpected auth response: {}", other.unwrap_or("missing type"))),
            }
        }
        .await;
        match handshake {
            Ok(msg) => checks.push(check_result("openuds handshake", true, msg)),
            Err(msg) => checks.push(check_result("openuds handshake", false, msg)),
        }
    } else {
        checks.push(check_result(
            "openuds handshake",
            false,
            format!(
                "missing: {}\nPMP server_config.yml:\nopenuds:\n  enabled: true\n  socket_path: \"{}\"\n  auth_token: \"\"\n  max_connections: 4\n  event_buffer_size: 1024\n  heartbeat_interval_secs: 60",
                openuds_path.display(), openuds_path.display()
            ),
        ));
    }

    // 5. capabilities (configured set)
    if let Ok((c, _)) = &cfg {
        checks.push(check_result(
            "pmp capabilities",
            !c.pmp.capabilities.is_empty(),
            format!("configured: {}", c.pmp.capabilities.join(", ")),
        ));
    }

    // 6. push config
    if let Ok((c, _)) = &cfg {
        let vapid = c.notifications.vapid_private_key_pem.is_some()
            && c.notifications.vapid_subject.is_some();
        checks.push(check_result("push (VAPID)", vapid, if vapid { "configured".into() } else { "not configured (WebPush disabled)".into() }));
    }

    // 7. GitHub config
    let gh = Secrets::from_env().map(|s| s.github_configured()).unwrap_or(false);
    checks.push(check_result("github oauth", gh, if gh { "configured".into() } else { "not configured (bind-only disabled)".into() }));

    // 8. URL reachability (best-effort)
    if let Ok((c, _)) = &cfg {
        let client = reqwest::Client::builder()
            .timeout(std::time::Duration::from_secs(5))
            .build()
            .ok();
        let mut reachable = true;
        let mut msg = String::new();
        if let Some(client) = client {
            for (label, url) in [
                ("api", c.server.public_url.as_str()),
                ("ppf", c.site.ppf_url.as_str()),
                ("panel", c.site.panel_url.as_str()),
            ] {
                match client.get(url).send().await {
                    Ok(resp) => {
                        let s = resp.status().as_u16();
                        msg.push_str(&format!("{label}={s} "));
                        if s >= 500 {
                            reachable = false;
                        }
                    }
                    Err(e) => {
                        reachable = false;
                        msg.push_str(&format!("{label}=ERR({}) ", redact(&e.to_string())));
                    }
                }
            }
        }
        checks.push(check_result("public urls", reachable, msg));
    }

    checks
}

fn resolve_config_for_doctor(args: &[String]) -> Result<(RuntimeConfig, String), String> {
    if let Some(path) = flag_value(args, "--config") {
        let text = std::fs::read_to_string(path).map_err(|e| e.to_string())?;
        let cfg = RuntimeConfig::from_toml_str(&text).map_err(|e| e.to_string())?;
        return Ok((cfg, path.to_string()));
    }
    if let Ok(path) = env::var("PPB_RUNTIME_CONFIG") {
        let text = std::fs::read_to_string(&path).map_err(|e| e.to_string())?;
        let cfg = RuntimeConfig::from_toml_str(&text).map_err(|e| e.to_string())?;
        return Ok((cfg, path));
    }
    if Path::new("config/ppb.toml").exists() {
        let text = std::fs::read_to_string("config/ppb.toml").map_err(|e| e.to_string())?;
        let cfg = RuntimeConfig::from_toml_str(&text).map_err(|e| e.to_string())?;
        return Ok((cfg, "config/ppb.toml".into()));
    }
    Ok((RuntimeConfig::default(), "<defaults>".into()))
}

// ── config check ───────────────────────────────────────────────

fn run_config_check(args: &[String]) -> ExitCode {
    let path = flag_value(args, "--config")
        .map(str::to_string)
        .or_else(|| env::var("PPB_RUNTIME_CONFIG").ok())
        .or_else(|| {
            if Path::new("config/ppb.toml").exists() {
                Some("config/ppb.toml".to_string())
            } else {
                None
            }
        });
    match path {
        Some(p) => {
            let text = match std::fs::read_to_string(&p) {
                Ok(t) => t,
                Err(e) => {
                    eprintln!("ppctl config check: read {p}: {e}");
                    return ExitCode::FAILURE;
                }
            };
            match RuntimeConfig::from_toml_str(&text) {
                Ok(_) => {
                    eprintln!("config OK: {p}");
                    ExitCode::SUCCESS
                }
                Err(e) => {
                    eprintln!("config INVALID: {p}: {e}");
                    ExitCode::FAILURE
                }
            }
        }
        None => {
            eprintln!("config check: no config file (PPB_RUNTIME_CONFIG or config/ppb.toml)");
            ExitCode::FAILURE
        }
    }
}

// ── root reset-password ────────────────────────────────────────

fn run_root_reset(args: &[String]) -> ExitCode {
    let env_file = flag_value(args, "--env-file")
        .map(PathBuf::from)
        .or_else(|| {
            let standard = PathBuf::from("/etc/ppb/ppb.env");
            standard.exists().then_some(standard)
        });
    if let Some(path) = env_file {
        if let Err(error) = load_env_file(&path) {
            eprintln!("ppctl root reset-password: env file {}: {error}", path.display());
            return ExitCode::FAILURE;
        }
    }
    let url = match env::var("PPB_DATABASE_URL") {
        Ok(u) if !u.is_empty() => u,
        _ => {
            eprintln!("ppctl root reset-password: PPB_DATABASE_URL required");
            return ExitCode::FAILURE;
        }
    };
    let rt = match tokio::runtime::Runtime::new() {
        Ok(r) => r,
        Err(e) => {
            eprintln!("ppctl root reset-password: {e}");
            return ExitCode::FAILURE;
        }
    };
    rt.block_on(async {
        let pool = match sqlx::postgres::PgPoolOptions::new().connect(&url).await {
            Ok(p) => p,
            Err(e) => {
                eprintln!("ppctl root reset-password: db connect: {e}");
                return ExitCode::FAILURE;
            }
        };
        match ppb_server::auth::root::RootAuthService::reset_password(&pool).await {
            Ok(password) => {
                eprintln!("Root password reset (print once, change on next login):");
                println!("{password}");
                ExitCode::SUCCESS
            }
            Err(e) => {
                eprintln!("ppctl root reset-password: {e}");
                ExitCode::FAILURE
            }
        }
    })
}

fn load_env_file(path: &Path) -> Result<(), String> {
    let text = std::fs::read_to_string(path).map_err(|error| error.to_string())?;
    for (line_number, line) in text.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let line = line.strip_prefix("export ").unwrap_or(line);
        let Some((key, value)) = line.split_once('=') else {
            return Err(format!("invalid assignment on line {}", line_number + 1));
        };
        let key = key.trim();
        if key.is_empty() || !key.chars().all(|c| c == '_' || c.is_ascii_alphanumeric()) {
            return Err(format!("invalid variable name on line {}", line_number + 1));
        }
        if env::var_os(key).is_none() {
            let value = value.trim().trim_matches(|c| c == '\'' || c == '"');
            env::set_var(key, value);
        }
    }
    Ok(())
}

// ── update ─────────────────────────────────────────────────────

fn run_update(args: &[String]) -> ExitCode {
    // V1: validate config (and optionally a staged config) then print the
    // stage→atomic-activate procedure (design §20.5). Actual activation is
    // done by deploy/update.sh / docker tag switch.
    let check = flag_value(args, "--check-config");
    if let Some(p) = check {
        let text = match std::fs::read_to_string(p) {
            Ok(t) => t,
            Err(e) => {
                eprintln!("ppctl update: read {p}: {e}");
                return ExitCode::FAILURE;
            }
        };
        if let Err(e) = RuntimeConfig::from_toml_str(&text) {
            eprintln!("ppctl update: staged config invalid: {e}");
            return ExitCode::FAILURE;
        }
        eprintln!("ppctl update: staged config valid: {p}");
    } else if run_config_check(&[]) != ExitCode::SUCCESS {
        return ExitCode::FAILURE;
    }
    eprintln!(
        "ppctl update: standard procedure\n\
         1. stage new release (download/verify checksum)\n\
         2. validate staged config\n\
         3. stop old service\n\
         4. atomic activate (symlink/image tag switch)\n\
         5. start + health check; rollback on failure\n\
         See deploy/update.sh and deploy/docker-compose.yml."
    );
    ExitCode::SUCCESS
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn redact_hides_db_password() {
        let s = "postgres://user:s3cret@db.example.com:5432/ppb";
        let out = redact(s);
        assert!(!out.contains("s3cret"));
        assert!(out.contains("db.example.com"));
    }

    #[test]
    fn redact_keeps_plain() {
        assert_eq!(redact("no secret here"), "no secret here");
    }

    #[test]
    fn random_b64_is_url_safe_length() {
        let s = random_b64(32);
        assert!(s.len() >= 43);
        assert!(!s.contains('\n'));
    }
}
